<?php require __DIR__.'/../includes/bootstrap.php'; require_login(); require __DIR__.'/../includes/layout.php';
if(isset($_GET['delete'])){check_csrf(); $id=(int)$_GET['delete'];$q=$db->prepare("DELETE FROM `book` WHERE `book_id`=?");$q->bind_param('i',$id);$q->execute();flash('Record deleted.');redirect('books.php');}
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf(); $vals=[]; foreach(['name', 'description', 'author', 'category'] as $c) $vals[] = post($c); $sets=[]; foreach(['name', 'description', 'author', 'category'] as $c) $sets[]="`$c`=?"; $types=str_repeat('s',count($vals)); $q=$db->prepare("INSERT INTO `book` (`name`, `description`, `author`, `category`) VALUES (".implode(',',array_fill(0,count($vals),'?')).")"); $q->bind_param($types,...$vals);$q->execute();flash('Record added successfully.');redirect('books.php');}
$rows=$db->query("SELECT `book_id`, `name`, `description`, `author`, `category` FROM `book` ORDER BY `book_id` DESC LIMIT 200"); page_header('Books', ['Dashboard'=>'dashboard.php']); ?>
<div class="panel"><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="form-grid"><p><label>Name</label><input name="name"></p><p><label>Description</label><input name="description"></p><p><label>Author</label><input name="author"></p><p><label>Category</label><input name="category"></p></div><button class="btn">Add book</button></form></div><br><div class="panel table-wrap"><table class="data"><tr><th>ID</th><th>Name</th><th>Description</th><th>Author</th><th>Category</th><th>Action</th></tr><?php while($r=$rows->fetch_assoc()): ?><tr><td><?=e($r["book_id"]) ?></td><td><?=e($r['name'])?></td><td><?=e($r['description'])?></td><td><?=e($r['author'])?></td><td><?=e($r['category'])?></td><td><a class="btn danger" data-confirm="Delete this record?" href="books.php?delete=<?=e($r['book_id'])?>&csrf=<?=e(csrf_token())?>">Delete</a></td></tr><?php endwhile; ?></table></div><?php page_footer(); ?>